import { Easing, useCurrentFrame, useVideoConfig } from "remotion";

/** Seconds keep playback consistent when a consumer chooses a different fps. */
export const INTRODUCING_DURATION = 32;
export const INTRODUCING_FPS = 60;
export const INTRODUCING_WIDTH = 1920;
export const INTRODUCING_HEIGHT = 1080;
export const introducingTimeline = [
  { id: "hook", name: "01 · You built the product", from: 0, duration: 2.5 },
  { id: "brand", name: "02 · Introducing", from: 2.5, duration: 2.5 },
  { id: "install", name: "03 · One command", from: 5, duration: 4 },
  { id: "gallery", name: "04 · Real components", from: 9, duration: 4 },
  { id: "customize", name: "05 · Make it yours", from: 13, duration: 5 },
  { id: "compose", name: "06 · Put it together", from: 18, duration: 4 },
  { id: "showcase", name: "07 · The finished video", from: 22, duration: 4 },
  { id: "ownership", name: "08 · Own the source", from: 26, duration: 3 },
  { id: "outro", name: "09 · Your next launch", from: 29, duration: 3 },
] as const;
export type SceneId = (typeof introducingTimeline)[number]["id"];

/** Reference fits are screen-space approximations, not original source curves. */
export const motion = {
  enter: Easing.bezier(0.16, 1, 0.3, 1),
  uiApproach: Easing.bezier(0.27, 0.624, 0.469, 0.802),
  morph: Easing.bezier(0.652, 0.343, 0.075, 0.909),
  pill: Easing.bezier(0.223, 0.625, 0.83, 0.887),
  camera: Easing.bezier(0.76, 0, 0.24, 1),
  exit: Easing.bezier(0.7, 0, 0.84, 0),
};
export const clamp = (value: number) => Math.max(0, Math.min(1, value));
export const mix = (a: number, b: number, progress: number) =>
  a + (b - a) * progress;
export function progress(
  time: number,
  start: number,
  duration: number,
  easing = motion.enter,
) {
  return easing(clamp((time - start) / Math.max(0.001, duration)));
}
export function useSceneTime() {
  return useCurrentFrame() / useVideoConfig().fps;
}
export function fitSize(
  text: string,
  size: number,
  width: number,
  factor = 0.57,
) {
  return Math.min(size, width / Math.max(1, Array.from(text).length * factor));
}
export function sceneFrames(
  scene: (typeof introducingTimeline)[number],
  fps: number,
) {
  const from = Math.round(scene.from * fps);
  return {
    from,
    durationInFrames: Math.round((scene.from + scene.duration) * fps) - from,
  };
}

import { AbsoluteFill, Sequence, useVideoConfig } from "remotion";
import { RadialBurst } from "@/components/remocn/radial-burst";
import { WordPush } from "@/components/remocn/word-push";
import type { SceneProps } from "./content";
import { fitSize, mix, motion, progress } from "./motion";
import { Cursor, center, WindowBar } from "./shared";

/** Actual registry components, isolated in a 1920×1080 preview canvas. */
export function ComponentPreview({
  kind,
  time,
  theme,
  content,
}: SceneProps & { kind: number; time: number }) {
  const { fps } = useVideoConfig();
  if (kind === 0)
    return (
      <AbsoluteFill style={{ background: theme.accent }}>
        <WordPush
          text={content.initialText}
          color={theme.ink}
          fontSize={fitSize(content.initialText, 230, 1650)}
          wordGap={12}
          speed={30 / fps}
        />
      </AbsoluteFill>
    );
  if (kind === 1)
    return (
      <RadialBurst
        color={theme.ink}
        accentColor={theme.paper}
        backgroundColor={theme.peach}
        intensity={1.1}
        echoes={2}
        loop
        speed={1}
      />
    );
  if (kind === 2) {
    const phase = time % 2;
    const p = progress(phase, 0.25, 1.2, motion.camera);
    return (
      <AbsoluteFill
        style={{ background: theme.ink, ...center, color: theme.paper }}
      >
        <span
          style={{ fontSize: 250, fontWeight: 500, letterSpacing: "-0.06em" }}
        >
          Aa
        </span>
        <AbsoluteFill
          style={{
            background: theme.mint,
            color: theme.ink,
            ...center,
            clipPath: `inset(0 ${100 - p * 100}% 0 0)`,
          }}
        >
          <span
            style={{ fontSize: 250, fontWeight: 500, letterSpacing: "-0.06em" }}
          >
            Aa
          </span>
        </AbsoluteFill>
        <div
          style={{
            position: "absolute",
            left: p * 1920,
            top: 0,
            height: 1080,
            width: 7,
            background: theme.paper,
          }}
        />
      </AbsoluteFill>
    );
  }
  const p = progress(time % 2.5, 0.3, 0.6);
  const click = time % 2.5 > 0.98;
  return (
    <AbsoluteFill style={{ background: theme.paper, ...center }}>
      <div
        style={{
          width: 880,
          height: 300,
          borderRadius: 180,
          background: click ? theme.accent : theme.ink,
          color: click ? theme.ink : theme.paper,
          ...center,
          fontSize: 105,
          fontWeight: 500,
          scale: click ? 0.97 : 1,
        }}
      >
        {click ? "✓ Added" : "Add component"}
      </div>
      <Cursor
        x={mix(1540, 1230, p)}
        y={mix(970, 610, p)}
        scale={4}
        pressed={click}
      />
    </AbsoluteFill>
  );
}

export function PreviewTile({
  x,
  y,
  width,
  height,
  kind,
  time,
  theme,
  content,
  rotate = 0,
  opacity = 1,
  startAt = 0,
}: SceneProps & {
  x: number;
  y: number;
  width: number;
  height: number;
  kind: number;
  time: number;
  rotate?: number;
  opacity?: number;
  startAt?: number;
}) {
  const { fps } = useVideoConfig();
  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y,
        width,
        height,
        borderRadius: 22,
        overflow: "hidden",
        boxShadow: "0 22px 45px #14131818",
        rotate: `${rotate}deg`,
        opacity,
      }}
    >
      <div
        style={{
          width: 1920,
          height: 1080,
          scale: width / 1920,
          transformOrigin: "0 0",
          position: "absolute",
          top: (height - (width * 1080) / 1920) / 2,
        }}
      >
        <Sequence from={Math.round(startAt * fps)} layout="none">
          <ComponentPreview
            kind={kind}
            time={time}
            theme={theme}
            content={content}
          />
        </Sequence>
      </div>
    </div>
  );
}

/** Shared across the gallery-to-editor cut so geometry and text stay continuous. */
export function EditingPreview({
  content,
  theme,
  text = content.initialText,
  color = theme.accent,
  wordGap = 10,
  previewStart = -1,
  opacity = 1,
  cursorTime = 0,
}: SceneProps & {
  text?: string;
  color?: string;
  wordGap?: number;
  previewStart?: number;
  opacity?: number;
  cursorTime?: number;
}) {
  const { fps } = useVideoConfig();
  const t = cursorTime;
  const cursorMove = progress(t, 0.65, 0.65);
  return (
    <div
      style={{
        position: "absolute",
        left: 960,
        top: 335,
        width: 820,
        height: 570,
        borderRadius: 22,
        background: theme.paper,
        overflow: "hidden",
        opacity,
      }}
    >
      <WindowBar title="live preview" />
      <div
        style={{
          position: "absolute",
          inset: "58px 0 0",
          background: theme.ink,
        }}
      >
        <Sequence
          key={previewStart}
          from={Math.round(previewStart * fps)}
          layout="none"
        >
          <WordPush
            text={text}
            color={color}
            fontSize={fitSize(text, 95, 730)}
            wordGap={wordGap}
            accel={0.88}
            speed={30 / fps}
          />
        </Sequence>
        <div
          style={{
            position: "absolute",
            bottom: 34,
            left: 34,
            display: "flex",
            gap: 14,
          }}
        >
          {[theme.accent, theme.peach, theme.mint].map((c) => (
            <div
              key={c}
              style={{
                width: 26,
                height: 26,
                borderRadius: "50%",
                background: c,
                outline: color === c ? `2px solid ${theme.paper}` : undefined,
                outlineOffset: 5,
              }}
            />
          ))}
        </div>
        <Cursor
          x={mix(720, 70, cursorMove)}
          y={mix(580, 455, cursorMove)}
          pressed={t > 1.3 && t < 1.46}
          color={theme.paper}
        />
      </div>
    </div>
  );
}

import type { SceneProps } from "../content";
import { fitSize, mix, progress, useSceneTime } from "../motion";
import { BrandMark, center, Eyebrow, Stage, Wordmark } from "../shared";

export function BrandScene(props: SceneProps) {
  const { content, theme } = props;
  const t = useSceneTime();
  const reveal = progress(t, 0, 0.58);
  const exit = progress(t, 2.02, 0.48);
  return (
    <Stage theme={theme}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          ...center,
          opacity: reveal * (1 - exit),
          scale: mix(0.83, 1, reveal),
        }}
      >
        {[0, 1, 2].map((i) => (
          <div
            key={i}
            style={{
              position: "absolute",
              width: 850 + i * 300,
              height: 850 + i * 300,
              border: `1px solid ${theme.accent}${i === 0 ? "30" : "16"}`,
              borderRadius: "50%",
              scale: mix(0.85, 1.03, progress(t, i * 0.06, 2.2)),
              rotate: `${i * 22 + t * 8}deg`,
              transform: "rotateX(62deg)",
            }}
          />
        ))}
        <div
          style={{
            position: "absolute",
            width: 1200,
            height: 800,
            top: 480,
            background: `radial-gradient(ellipse, ${theme.accent}35, transparent 66%)`,
          }}
        />
        <div
          style={{
            ...center,
            flexDirection: "column",
            gap: 44,
            translate: `0 ${-exit * 150}px`,
          }}
        >
          <Eyebrow
            style={{ color: theme.accent, opacity: progress(t, 0.35, 0.3) }}
          >
            Introducing
          </Eyebrow>
          <Wordmark {...props} size={260} color={theme.paper} />
          <div
            style={{
              fontSize: fitSize(content.tagline, 44, 1600),
              letterSpacing: "-0.025em",
              opacity: progress(t, 0.55, 0.4),
            }}
          >
            {content.tagline}
          </div>
        </div>
      </div>
      <div
        style={{
          position: "absolute",
          left: mix(0, 854, reveal),
          top: mix(0, 350, reveal),
          width: mix(1920, 212, reveal),
          height: mix(1080, 212, reveal),
          borderRadius: mix(0, 52, reveal),
          background: theme.accent,
          ...center,
          opacity: 1 - progress(t, 0.28, 0.26),
          scale: mix(1, 0.8, reveal),
        }}
      >
        <BrandMark {...props} size={100} color={theme.ink} />
      </div>
      <div
        style={{
          position: "absolute",
          left: 220,
          top: 436,
          width: 1480,
          height: 208,
          borderRadius: 24,
          border: `1px solid ${theme.accent}55`,
          background: "#201e26",
          opacity: exit,
          scale: mix(0.72, 1, exit),
        }}
      />
    </Stage>
  );
}

import type { SceneProps } from "../content";
import { fitSize, mix, motion, progress, useSceneTime } from "../motion";
import { PreviewTile } from "../previews";
import { CornerLabel, Headline, mono, Stage } from "../shared";

export function ComposeScene(props: SceneProps) {
  const { content, theme } = props;
  const t = useSceneTime();
  const gather = progress(t, 0.6, 0.65, motion.morph);
  const play = progress(t, 1.3, 2.1, (v) => v);
  const takeover = progress(t, 3.55, 0.45, motion.camera);
  const colors = [theme.accent, theme.peach, theme.mint];
  return (
    <Stage theme={theme} light>
      <CornerLabel theme={theme} light>
        {content.productName} / One composition
      </CornerLabel>
      <div
        style={{
          position: "absolute",
          left: 120,
          top: 168,
          opacity: 1 - takeover,
        }}
      >
        <Headline text={content.timelineTitle} time={t} size={105} />
      </div>
      <div
        style={{
          position: "absolute",
          left: 150,
          top: 650,
          width: 1620,
          height: 290,
          opacity: progress(t, 0.5, 0.45) * (1 - takeover),
          borderTop: `1px solid ${theme.ink}22`,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: -32,
            display: "flex",
            justifyContent: "space-between",
            fontFamily: mono,
            fontSize: 17,
            color: theme.muted,
          }}
        >
          {["00:00", "00:02", "00:04", "00:06", "00:08"].map((s) => (
            <span key={s}>{s}</span>
          ))}
        </div>
        {colors.map((c, i) => (
          <div
            key={c}
            style={{
              position: "absolute",
              left: 0,
              top: 22 + i * 80,
              height: 62,
              width: 1620,
              borderRadius: 12,
              background: "#14131805",
              border: "1px solid #1413180b",
            }}
          />
        ))}
        <div
          style={{
            position: "absolute",
            left: 1620 * play,
            top: -10,
            bottom: 12,
            width: 3,
            background: theme.ink,
            zIndex: 4,
          }}
        >
          <div
            style={{
              width: 13,
              height: 13,
              background: theme.ink,
              marginLeft: -5,
              rotate: "45deg",
            }}
          />
        </div>
      </div>
      {[0, 1, 2].map((i) => {
        const x = mix(150 + i * 560, 160 + i * 500, gather);
        const y = mix(344, 672 + i * 80, gather);
        return (
          <div key={i} style={{ opacity: 1 - takeover }}>
            <PreviewTile
              {...props}
              kind={i}
              time={t}
              x={x}
              y={y}
              width={mix(500, 590, gather)}
              height={mix(240, 62, gather)}
              rotate={mix((i - 1) * 4, 0, gather)}
            />
            <div
              style={{
                position: "absolute",
                left: x,
                top: y,
                width: mix(500, 590, gather),
                height: mix(240, 62, gather),
                background: colors[i],
                borderRadius: 12,
                opacity: gather,
              }}
            />
            <div
              style={{
                position: "absolute",
                left: x + 22,
                top: y + 16,
                fontFamily: mono,
                fontSize: 21,
                opacity: gather,
                color: theme.ink,
                background: `${colors[i]}e8`,
                paddingRight: 18,
              }}
            >
              {["01  Intro", "02  Motion", "03  Outro"][i]}
            </div>
          </div>
        );
      })}
      <div
        style={{
          position: "absolute",
          left: mix(710, 0, takeover),
          top: mix(332, 0, takeover),
          width: mix(500, 1920, takeover),
          height: mix(240, 1080, takeover),
          background: theme.accent,
          borderRadius: mix(18, 0, takeover),
          opacity: progress(t, 1.13, 0.3),
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          overflow: "hidden",
          boxShadow: "0 20px 65px #14131812",
        }}
      >
        <div
          style={{
            fontSize: mix(
              fitSize(content.showcaseTitle, 54, 450),
              fitSize(content.showcaseTitle, 206, 1700),
              takeover,
            ),
            letterSpacing: "-0.065em",
            fontWeight: 500,
            textAlign: "center",
            padding: 20,
          }}
        >
          {content.showcaseTitle}
        </div>
      </div>
      <div
        style={{
          position: "absolute",
          top: 981,
          left: 150,
          fontSize: 18,
          letterSpacing: "0.1em",
          color: theme.muted,
          opacity: 1 - takeover,
        }}
      >
        REMOTION COMPOSITION
      </div>
    </Stage>
  );
}

