export function Headline({
  text,
  time,
  start = 0,
  size = 114,
  width = 1660,
  color,
  style,
}: {
  text: string;
  time: number;
  start?: number;
  size?: number;
  width?: number;
  color?: string;
  style?: CSSProperties;
}) {
  const words = text.split(/\s+/);
  return (
    <div
      style={{
        width,
        fontSize: fitSize(text, size, width),
        fontWeight: 500,
        letterSpacing: "-0.055em",
        lineHeight: 1.1,
        color,
        ...style,
      }}
    >
      {words.map((word, i) => {
        const p = progress(time, start + i * 0.065, 0.32);
        return (
          <span
            key={`${i}-${word}`}
            style={{
              display: "inline-block",
              marginRight: "0.24em",
              opacity: p,
              translate: `0 ${mix(60, 0, p)}px`,
              filter: p < 1 ? `blur(${(1 - p) * 9}px)` : undefined,
            }}
          >
            {word}
          </span>
        );
      })}
    </div>
  );
}

